// @ts-nocheck
import { useEffect, useState } from "react";
import "./styles.css";
import logoSrc from "./logo.png";

type Props = {
  count: number;
  thinner: boolean;
  commaPositions: number[];
};

const params = window.location.search.substr(1);

function Counter(props: Props) {
  const all = params.includes("all");
  const [digitElements, setDigitElements] = useState([]);
  const [oldCount, setOldCount] = useState(props.count.toString());
  const [initial, setInitial] = useState(true);

  const [viewport, setViewport] = useState({
    width: window.innerWidth,
    height: window.innerHeight,
  });

  useEffect(() => {
    const updateViewport = () => {
      setViewport({
        width: window.innerWidth,
        height: window.innerHeight,
      });
    };

    window.addEventListener("resize", updateViewport);

    return () => {
      window.removeEventListener("resize", updateViewport);
    };
  }, []);

  const animationLength = 400;

  const background = (
    <>
      <div className="bg1"></div>
      <div className="bg2"></div>
      <div className="bg3"></div>
      <div className="bg4"></div>
    </>
  );

  const logoImage = (
    <div className="digit-image-frame">
      <img src={logoSrc} alt="*" className="digit-image" draggable={false} />
    </div>
  );

  const setDigitElementsFunc = (newNumber: number, refresh?: boolean) => {
    const newNumberArray = newNumber.toString().split("");
    const oldNumberArray = oldCount.split("");
    const newDigits = [];

    const extraClasses = ` ${props.thinner ? "thin" : ""} ${all ? "all" : ""}`;

    for (let i = 0; i < newNumberArray.length; i++) {
      const comma = (
        <div key={`${i}comma`} className="comma">
          ,
        </div>
      );

      if (newNumberArray[i] === "*") {
        newDigits.push(<div key={i}>{logoImage}</div>);
        continue;
      }

      const includeComma = props.commaPositions.includes(i);

      if (refresh) {
        newDigits.push(
          <div key={i} className={`digit ${extraClasses}`}>
            {background}
            <div className="top">{newNumberArray[i]}</div>
            <div className="bottom">
              {newNumberArray[i]}
              {includeComma ? comma : null}
            </div>
          </div>,
        );
      } else if (newNumberArray[i] !== oldNumberArray[i]) {
        newDigits.push(
          <div key={i} className={`digit ${extraClasses}`}>
            {background}
            <div className="top">{newNumberArray[i]}</div>
            <div className="bottom">
              {oldNumberArray[i]}
              {includeComma ? comma : null}
            </div>
            <div className="half">{oldNumberArray[i]}</div>
            <div className="bottom-half">
              {newNumberArray[i]}
              {includeComma ? comma : null}
            </div>
          </div>,
        );
      } else {
        newDigits.push(
          <div key={i} className={`digit ${extraClasses}`}>
            {background}
            <div className="top">{oldNumberArray[i]}</div>
            <div className="bottom">
              {oldNumberArray[i]}
              {includeComma ? comma : null}
            </div>
          </div>,
        );
      }
    }

    setDigitElements(newDigits);
  };

  useEffect(() => {
    if (initial) {
      setInitial(false);
      setDigitElementsFunc(props.count, true);
      return;
    }

    setDigitElementsFunc(props.count);

    const oldCountTimeout = window.setTimeout(() => {
      setOldCount(props.count.toString());
    }, animationLength / 2);

    const refreshTimeout = window.setTimeout(() => {
      setDigitElementsFunc(props.count, true);
    }, animationLength + 50);

    return () => {
      window.clearTimeout(oldCountTimeout);
      window.clearTimeout(refreshTimeout);
    };
  }, [props.count, props.commaPositions]);

  const designWidth = all ? 2976 / 2 : 2560;
  const designHeight = all ? 780 / 2 : 1080;

  return (
    <div className="viewport">
      <div
        className={`container ${all ? "all" : ""}`}
        style={{
          transform: `scale(${viewport.width / designWidth}, ${
            viewport.height / designHeight
          })`,
        }}
      >
        {digitElements}
      </div>
    </div>
  );
}

export default Counter;
